pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response is JSON", function () {
    pm.response.to.be.json;
});

const users = pm.response.json();

pm.test("Response is a non-empty array", function () {
    pm.expect(users).to.be.an("array").that.is.not.empty;
});

pm.test("Response contains 10 users", function () {
    pm.expect(users).to.have.lengthOf(10);
});

pm.test("Every user has id, name and email", function () {
    users.forEach(function (user) {
        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("name");
        pm.expect(user).to.have.property("email");
    });
});

pm.environment.set("userId", users[0].id);

console.log("Saved User ID:", users[0].id);
pm.environment.set("userPhone", users[0].phone);

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

const responseData = pm.response.json();

pm.test("Returned ID matches saved ID", function () {
    pm.expect(responseData.id).to.eql(Number(pm.environment.get("userId")));
});

pm.test("Updated name is correct", function () {
    pm.expect(responseData.name).to.eql(pm.variables.get("updatedName"));
});

pm.test("Updated email is correct", function () {
    pm.expect(responseData.email).to.eql(pm.variables.get("updatedEmail"));
});

pm.test("Updated company is correct", function () {
    pm.expect(responseData.company.name).to.eql(pm.variables.get("updatedCompanyName"));
});

pm.test("Phone is not empty", function () {
    pm.expect(responseData.phone).to.be.a("string").and.not.empty;
});

